	if err := fs.WalkDir(golang.Queries, "queries", walk); err != nil {
		log.Fatal(err)
	}
	// Output:
	// (source_file (package_clause (package_identifier)))
	// patterns in queries/highlights.scm: 15
	// patterns in queries/tags.scm: 11
